import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor conv_transpose3d_cute(
    torch::Tensor x, torch::Tensor weight, torch::Tensor bias,
    int64_t stride_d, int64_t stride_h, int64_t stride_w,
    int64_t pad_d, int64_t pad_h, int64_t pad_w,
    int64_t out_pad_d, int64_t out_pad_h, int64_t out_pad_w,
    int64_t groups);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
using namespace cute;
// Register-blocked kernel: each CTA computes COTILE output channels at once,
// reusing the same staged input row (shared memory) across all of them.
// This amortizes the reusable-input global load cost across multiple
// output channels instead of reloading it once per output channel.
template<int COTILE, int OWTILE>
__global__ void conv_transpose3d_kernel(
    float const* __restrict__ x,
    float const* __restrict__ w,
    float const* __restrict__ bias,
    float* __restrict__ y,
    int N, int Cin, int D, int H, int W,
    int Cout, int Dout, int Hout, int Wout,
    int kD, int kH, int kW,
    int sD, int sH, int sW,
    int pD, int pH, int pW,
    int groups)
{
    int Cin_per_group  = Cin / groups;
    int Cout_per_group = Cout / groups;
    int num_co_tiles = Cout / COTILE;
    int bidx = blockIdx.x; // encodes (n, co_tile)
    int n  = bidx / num_co_tiles;
    int co_tile_idx = bidx % num_co_tiles;
    int co_base = co_tile_idx * COTILE;
    int group    = co_base / Cout_per_group;
    int bidy = blockIdx.y; // encodes (od, oh): each block now owns a single (od, oh) output row instead of looping over all oh serially inside one block. The previous scheme collapsed all of Hout into one CTA, leaving the grid far too small (only N*num_co_tiles x Dout x grid_z blocks) and, for narrow Wout, shrinking blockDim.x down to a single warp -- badly under-utilizing the GPU. Spreading oh across the grid multiplies the number of independent CTAs by Hout, giving the scheduler far more concurrent work to fill the SMs, without changing the amount of global/shared memory traffic per output element.
    int od = bidy / Hout;
    int oh = bidy % Hout;
    int TILE_W = blockDim.x;
    // Register-blocked output-width tiling: each thread now computes OWTILE
    // contiguous-strided output pixels instead of just one. This lets the
    // per-(kd,kh,kw,ci_local) weight value read from shared memory be loaded
    // ONCE per thread and reused across all OWTILE output pixels, amortizing
    // shared-memory weight reads (and their associated bank-conflict/latency
    // cost) by a factor of OWTILE on top of the existing output-channel
    // register blocking (COTILE).
    int ow_base = blockIdx.z * TILE_W * OWTILE;
    int ow[OWTILE];
    bool valid_ow[OWTILE];
    #pragma unroll
    for (int t = 0; t < OWTILE; ++t) {
        ow[t] = ow_base + t * TILE_W + threadIdx.x;
        valid_ow[t] = ow[t] < Wout;
    }
    // Global memory tensors (CuTe layouts)
    Tensor gX = make_tensor(make_gmem_ptr(x),
        make_shape(N, Cin, D, H, W),
        make_stride(Cin * D * H * W, D * H * W, H * W, W, 1));
    Tensor gW = make_tensor(make_gmem_ptr(w),
        make_shape(Cin, Cout_per_group, kD, kH, kW),
        make_stride(Cout_per_group * kD * kH * kW, kD * kH * kW, kH * kW, kW, 1));
    Tensor gY = make_tensor(make_gmem_ptr(y),
        make_shape(N, Cout, Dout, Hout, Wout),
        make_stride(Cout * Dout * Hout * Wout, Dout * Hout * Wout, Hout * Wout, Wout, 1));
    // Shared memory: weight slices for COTILE output channels across all ci in
    // group, followed by a scratch buffer used to stage reusable input rows for
    // ALL Cin_per_group channels at once (shape [Cin_per_group, W]), shared
    // across ALL COTILE output channels in this CTA. Loading every channel's
    // row for a given (kd, kh) tap in one cooperative pass and syncing once
    // amortizes the __syncthreads() overhead across Cin_per_group channels
    // instead of paying a sync pair once per channel.
    extern __shared__ float smem[];
    Tensor smemW = make_tensor(make_smem_ptr(smem),
        make_shape(COTILE, Cin_per_group, kD, kH, kW),
        make_stride(Cin_per_group * kD * kH * kW, kD * kH * kW, kH * kW, kW, 1));
    float* smemRow = smem + COTILE * Cin_per_group * kD * kH * kW;
    int per_co_size = Cin_per_group * kD * kH * kW;
    int wsize_total = COTILE * per_co_size;
    for (int idx = threadIdx.x; idx < wsize_total; idx += blockDim.x) {
        int t = idx / per_co_size;
        int rem0 = idx % per_co_size;
        int ci_local = rem0 / (kD * kH * kW);
        int rem = rem0 % (kD * kH * kW);
        int kd = rem / (kH * kW);
        int rem2 = rem % (kH * kW);
        int kh = rem2 / kW;
        int kw = rem2 % kW;
        int co = co_base + t;
        int co_local = co % Cout_per_group;
        int ci = group * Cin_per_group + ci_local;
        smemW(t, ci_local, kd, kh, kw) = gW(ci, co_local, kd, kh, kw);
    }
    __syncthreads();
    float acc[COTILE][OWTILE];
    #pragma unroll
    for (int co = 0; co < COTILE; ++co) {
        #pragma unroll
        for (int t = 0; t < OWTILE; ++t) acc[co][t] = 0.f;
    }
    for (int kd = 0; kd < kD; ++kd) {
        int id_num = od + pD - kd;
        bool id_valid = (id_num % sD == 0);
        int id = id_num / sD;
        id_valid = id_valid && id >= 0 && id < D;
        for (int kh = 0; kh < kH; ++kh) {
            int ih_num = oh + pH - kh;
            bool ih_valid = (ih_num % sH == 0);
            int ih = ih_num / sH;
            ih_valid = ih_valid && ih >= 0 && ih < H;
            bool tap_valid = id_valid && ih_valid;
            // Cooperative load of the reusable input rows x[n, ci, id, ih, :]
            // for ALL Cin_per_group channels into shared memory at once; shared
            // across all ow in this tile, all kw taps, and all COTILE output
            // channels in this CTA. A single __syncthreads() then covers the
            // whole channel dimension instead of one sync per channel.
            if (tap_valid) {
                if ((W & 3) == 0) {
                    // Vectorized (float4) global-memory loads of the reusable input
                    // row for each channel, reducing the number of global memory
                    // transactions by 4x compared to scalar per-element loads while
                    // still writing individual floats into shared memory (avoiding
                    // any dynamic-shared-memory alignment assumptions).
                    int W4 = W >> 2;
                    int total4 = Cin_per_group * W4;
                    for (int idx = threadIdx.x; idx < total4; idx += blockDim.x) {
                        int ci_local = idx / W4;
                        int w4 = idx % W4;
                        int ci = group * Cin_per_group + ci_local;
                        const float4* rowPtr4 = reinterpret_cast<const float4*>(&gX(n, ci, id, ih, w4 * 4));
                        float4 v = *rowPtr4;
                        float* dst = smemRow + ci_local * W + w4 * 4;
                        dst[0] = v.x; dst[1] = v.y; dst[2] = v.z; dst[3] = v.w;
                    }
                } else {
                    int total = Cin_per_group * W;
                    for (int idx = threadIdx.x; idx < total; idx += blockDim.x) {
                        int ci_local = idx / W;
                        int w_idx = idx % W;
                        int ci = group * Cin_per_group + ci_local;
                        smemRow[ci_local * W + w_idx] = gX(n, ci, id, ih, w_idx);
                    }
                }
            }
            __syncthreads();
            if (tap_valid) {
                for (int ci_local = 0; ci_local < Cin_per_group; ++ci_local) {
                    float const* rowPtr = smemRow + ci_local * W;
                    for (int kw = 0; kw < kW; ++kw) {
                        float wv[COTILE];
                        #pragma unroll
                        for (int co = 0; co < COTILE; ++co) {
                            wv[co] = smemW(co, ci_local, kd, kh, kw);
                        }
                        #pragma unroll
                        for (int t = 0; t < OWTILE; ++t) {
                            if (!valid_ow[t]) continue;
                            int iw_num = ow[t] + pW - kw;
                            if (iw_num % sW != 0) continue;
                            int iw = iw_num / sW;
                            if (iw < 0 || iw >= W) continue;
                            float xv = rowPtr[iw];
                            #pragma unroll
                            for (int co = 0; co < COTILE; ++co) {
                                acc[co][t] += xv * wv[co];
                            }
                        }
                    }
                }
            }
            __syncthreads();
        }
    }
    #pragma unroll
    for (int t = 0; t < OWTILE; ++t) {
        if (!valid_ow[t]) continue;
        #pragma unroll
        for (int co = 0; co < COTILE; ++co) {
            int co_idx = co_base + co;
            float v = acc[co][t];
            if (bias != nullptr) v += bias[co_idx];
            gY(n, co_idx, od, oh, ow[t]) = v;
        }
    }
}
template<int COTILE, int OWTILE>
static void launch_conv_transpose3d(
    float const* x_ptr, float const* w_ptr, float const* bias_ptr, float* y_ptr,
    int N, int Cin, int D, int H, int W,
    int Cout, int Dout, int Hout, int Wout,
    int kD, int kH, int kW,
    int sD, int sH, int sW,
    int pD, int pH, int pW,
    int groups, int Cin_per_group,
    cudaStream_t stream)
{
    int per_co_size = Cin_per_group * kD * kH * kW;
    size_t smem_bytes = (size_t)COTILE * per_co_size * sizeof(float) + (size_t)Cin_per_group * (size_t)W * sizeof(float);
    // Use a fixed, sufficiently large CTA width (128 threads) for the
    // cooperative shared-memory staging loops (weight-tile load and the
    // per-(kd,kh) reusable input-row load), instead of shrinking blockDim.x
    // down to match Wout/OWTILE. Those staging loops iterate
    // total_elements/blockDim.x times regardless of how many threads end up
    // with a valid output pixel, so a small block (e.g. 32 threads for a
    // narrow Wout) pays a much larger serialized cost to fill shared memory
    // even though the extra threads in a wider block cost almost nothing
    // extra (they simply skip via valid_ow during the output-compute phase).
    // Keeping TILE_W fixed at 128 maximizes cooperative-load parallelism
    // while OWTILE still governs the per-thread output register blocking.
    int TILE_W = 128;
    int grid_z = (Wout + TILE_W * OWTILE - 1) / (TILE_W * OWTILE);
    int num_co_tiles = Cout / COTILE;
    dim3 grid((unsigned)(N * num_co_tiles), (unsigned)(Dout * Hout), (unsigned)grid_z);
    dim3 blk((unsigned)TILE_W);
    if (smem_bytes > 48 * 1024) {
        cudaError_t attr_err = cudaFuncSetAttribute(conv_transpose3d_kernel<COTILE, OWTILE>,
            cudaFuncAttributeMaxDynamicSharedMemorySize, (int)smem_bytes);
        TORCH_CHECK(attr_err == cudaSuccess,
            "conv_transpose3d_cute: cudaFuncSetAttribute failed for smem_bytes=",
            (long long)smem_bytes, " : ", cudaGetErrorString(attr_err));
    }
    conv_transpose3d_kernel<COTILE, OWTILE><<<grid, blk, smem_bytes, stream>>>(
        x_ptr, w_ptr, bias_ptr, y_ptr,
        N, Cin, D, H, W,
        Cout, Dout, Hout, Wout,
        kD, kH, kW,
        sD, sH, sW,
        pD, pH, pW,
        groups);
}
torch::Tensor conv_transpose3d_cute(
    torch::Tensor x, torch::Tensor weight, torch::Tensor bias,
    int64_t stride_d, int64_t stride_h, int64_t stride_w,
    int64_t pad_d, int64_t pad_h, int64_t pad_w,
    int64_t out_pad_d, int64_t out_pad_h, int64_t out_pad_w,
    int64_t groups)
{
    TORCH_CHECK(x.is_cuda() && weight.is_cuda(), "x and weight must be CUDA tensors");
    TORCH_CHECK(x.scalar_type() == at::kFloat && weight.scalar_type() == at::kFloat,
                "Expect float32 tensors");
    TORCH_CHECK(x.dim() == 5, "x must be 5D (N,Cin,D,H,W)");
    TORCH_CHECK(weight.dim() == 5, "weight must be 5D (Cin,Cout/groups,kD,kH,kW)");
    auto x_c = x.contiguous();
    auto w_c = weight.contiguous();
    int N   = (int)x_c.size(0);
    int Cin = (int)x_c.size(1);
    int D   = (int)x_c.size(2);
    int H   = (int)x_c.size(3);
    int W   = (int)x_c.size(4);
    int Cout_per_group = (int)w_c.size(1);
    int kD = (int)w_c.size(2);
    int kH = (int)w_c.size(3);
    int kW = (int)w_c.size(4);
    int Cout = Cout_per_group * (int)groups;
    int sD = (int)stride_d, sH = (int)stride_h, sW = (int)stride_w;
    int pD = (int)pad_d, pH = (int)pad_h, pW = (int)pad_w;
    int opD = (int)out_pad_d, opH = (int)out_pad_h, opW = (int)out_pad_w;
    int Dout = (D - 1) * sD - 2 * pD + kD + opD;
    int Hout = (H - 1) * sH - 2 * pH + kH + opH;
    int Wout = (W - 1) * sW - 2 * pW + kW + opW;
    auto y = torch::empty({N, Cout, Dout, Hout, Wout}, x_c.options());
    float const* bias_ptr = nullptr;
    torch::Tensor bias_c;
    if (bias.defined() && bias.numel() > 0) {
        bias_c = bias.contiguous();
        bias_ptr = bias_c.data_ptr<float>();
    }
    int Cin_per_group = Cin / (int)groups;
    // Choose the largest output-channel register-blocking factor that evenly
    // divides Cout_per_group (so a CTA's channel tile never crosses a group
    // boundary) AND whose resulting dynamic shared memory footprint actually
    // fits within this device's opt-in shared memory limit, amortizing
    // reusable input-row loads across multiple output channels held in
    // registers without exceeding hardware resource limits.
    int dev = 0;
    cudaGetDevice(&dev);
    int max_optin_smem = 0;
    cudaDeviceGetAttribute(&max_optin_smem, cudaDevAttrMaxSharedMemoryPerBlockOptin, dev);
    if (max_optin_smem <= 0) {
        max_optin_smem = 48 * 1024;
    }
    auto smem_needed_for = [&](int cotile) -> size_t {
        size_t per_co_size_bytes = (size_t)Cin_per_group * (size_t)kD * (size_t)kH * (size_t)kW * sizeof(float);
        return (size_t)cotile * per_co_size_bytes + (size_t)Cin_per_group * (size_t)W * sizeof(float);
    };
    int COTILE = 1;
    if (Cout_per_group % 8 == 0 && smem_needed_for(8) <= (size_t)max_optin_smem) COTILE = 8;
    else if (Cout_per_group % 4 == 0 && smem_needed_for(4) <= (size_t)max_optin_smem) COTILE = 4;
    else if (Cout_per_group % 2 == 0 && smem_needed_for(2) <= (size_t)max_optin_smem) COTILE = 2;
    else COTILE = 1;
    TORCH_CHECK(smem_needed_for(COTILE) <= (size_t)max_optin_smem,
        "conv_transpose3d_cute: required shared memory exceeds device limit even for COTILE=1");
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    switch (COTILE) {
        case 8:
            launch_conv_transpose3d<8, 4>(
                x_c.data_ptr<float>(), w_c.data_ptr<float>(), bias_ptr, y.data_ptr<float>(),
                N, Cin, D, H, W, Cout, Dout, Hout, Wout,
                kD, kH, kW, sD, sH, sW, pD, pH, pW,
                (int)groups, Cin_per_group, stream);
            break;
        case 4:
            launch_conv_transpose3d<4, 4>(
                x_c.data_ptr<float>(), w_c.data_ptr<float>(), bias_ptr, y.data_ptr<float>(),
                N, Cin, D, H, W, Cout, Dout, Hout, Wout,
                kD, kH, kW, sD, sH, sW, pD, pH, pW,
                (int)groups, Cin_per_group, stream);
            break;
        case 2:
            launch_conv_transpose3d<2, 4>(
                x_c.data_ptr<float>(), w_c.data_ptr<float>(), bias_ptr, y.data_ptr<float>(),
                N, Cin, D, H, W, Cout, Dout, Hout, Wout,
                kD, kH, kW, sD, sH, sW, pD, pH, pW,
                (int)groups, Cin_per_group, stream);
            break;
        default:
            launch_conv_transpose3d<1, 4>(
                x_c.data_ptr<float>(), w_c.data_ptr<float>(), bias_ptr, y.data_ptr<float>(),
                N, Cin, D, H, W, Cout, Dout, Hout, Wout,
                kD, kH, kW, sD, sH, sW, pD, pH, pW,
                (int)groups, Cin_per_group, stream);
            break;
    }
    TORCH_CHECK(cudaGetLastError() == cudaSuccess, "conv_transpose3d_cute launch failed");
    return y;
}
"""

_cute_ext = load_inline(
    name="cute_conv_transpose3d_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["conv_transpose3d_cute"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3", "--expt-relaxed-constexpr"],
    extra_include_paths=["/workspace/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple,
                 stride: tuple = (1, 1, 1), padding: tuple = (0, 0, 0),
                 output_padding: tuple = (0, 0, 0), groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        # Use nn.ConvTranspose3d only to hold/initialize parameters identically to reference
        ref = nn.ConvTranspose3d(in_channels, out_channels, kernel_size,
                                  stride=stride, padding=padding,
                                  output_padding=output_padding, groups=groups, bias=bias)
        self.weight = nn.Parameter(ref.weight.data.clone())
        if bias:
            self.bias = nn.Parameter(ref.bias.data.clone())
        else:
            self.register_parameter('bias', None)

        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.groups = groups

        self._ext = _cute_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.contiguous().cuda().float()
        weight = self.weight.contiguous().cuda().float()
        bias = self.bias.contiguous().cuda().float() if self.bias is not None else torch.Tensor()

        sd, sh, sw = self.stride
        pd, ph, pw = self.padding
        opd, oph, opw = self.output_padding

        return self._ext.conv_transpose3d_cute(
            x, weight, bias,
            sd, sh, sw,
            pd, ph, pw,
            opd, oph, opw,
            self.groups
        )

